export class LodShaders {
  static vertex = `
            #include <common>
            #include <clipping_planes_pars_vertex>

            attribute float itemFilter;
            uniform vec2 lodSize;
            attribute vec3 itemFirst;
            attribute vec3 itemLast;
            attribute vec3 itemHighlightColor;

            float lodWidth = 2.0;
            
            void cutLodLine(const in vec4 first, inout vec4 second ) {
                float projValue1 = projectionMatrix[2][2];
                float projValue2 = projectionMatrix[3][2];
                float approxResult = -(projValue2 / projValue1) / 2.0;
                float diff1 = approxResult - first.z;
                float diff2 = second.z - first.z;
                float cutFilter = diff1 / diff2;
                second.xyz = mix(first.xyz, second.xyz, cutFilter);
            }
                
            varying float vHighlight;
            varying vec3 vHighlightColor;

            void main() {
                if (itemFilter == 0.0) {
                    gl_Position = vec4(0,0,0,0);
                    return;
                }

                vHighlight = itemFilter > 1.5 ? 1.0 : 0.0;
                vHighlightColor = itemHighlightColor;

                vec4 rawFirst = vec4(itemFirst, 1.0);
                vec4 rawLast = vec4(itemLast, 1.0);
                vec4 first = modelViewMatrix * rawFirst;
                vec4 last = modelViewMatrix * rawLast;
                
                bool lodPerspective = projectionMatrix[2][3] == -1.0;
                if (lodPerspective) {
                    bool firstCut = first.z < 0.0 && last.z >= 0.0;
                    bool lastCut = last.z < 0.0 && first.z >= 0.0;
                    if (firstCut) {
                        cutLodLine( first, last );
                    } else if (lastCut) {
                        cutLodLine( last, first );
                    }
                }

                vec4 firstCut = projectionMatrix * first;
                vec4 lastCut = projectionMatrix * last;
                vec3 firstNdc = firstCut.xyz / firstCut.w;
                vec3 lastNdc = lastCut.xyz / lastCut.w;

                vec2 lodOrientation = lastNdc.xy - firstNdc.xy;

                float lodRatio = lodSize.x / lodSize.y;
                lodOrientation.x *= lodRatio;
                lodOrientation = normalize(lodOrientation);
                
                vec2 lodDistance = vec2(lodOrientation.y, - lodOrientation.x);
                lodOrientation.x /= lodRatio;
                lodDistance.x /= lodRatio;

                if (position.x < 0.0) { 
                    lodDistance *= - 1.0;
                }

                if (position.y < 0.0) {
                    lodDistance += -lodOrientation;
                } else if (position.y > 1.0) {
                    lodDistance += lodOrientation;
                }

                lodDistance *= lodWidth;
                lodDistance /= lodSize.y;

                bool isFirst = position.y < 0.5;
                vec4 lodPosition = isFirst ? firstCut : lastCut;
                lodDistance *= lodPosition.w;
                lodPosition.xy += lodDistance;
                gl_Position = lodPosition;

                vec4 mvPosition = isFirst ? first : last;
                #include <clipping_planes_vertex>
            }
    `;

  static fragment = `
            #include <common>
            #include <clipping_planes_pars_fragment>

            uniform vec3 lodColor;
            uniform float lodOpacity;
            uniform vec3 highlightColor;
            uniform float highlightOpacity;

            varying float vHighlight;
            varying vec3 vHighlightColor;

            // Deferred capture: alongside its line colour (location 0), a LOD line
            // can emit the same auxiliary geometry attachments the SHELL surfaces do
            // (see capture-emission.ts), so a single-pass deferred renderer captures
            // it into the same G-buffer and contours / occludes it like the thin
            // surface it stands in for. Gated by CAPTURE_EMISSION so ordinary line
            // rendering is unchanged.
            #ifdef CAPTURE_EMISSION
              layout(location = 1) out vec2 gCaptureNormal;
              layout(location = 2) out vec4 gCaptureFaceId;
            #endif

            // Ghost (x-ray): when active, the LOD line is the de-emphasized
            // CONTEXT representation, so it is faded (4x4 Bayer screen-door
            // discard) and desaturated, consistent with the SHELL ghost (see
            // ghost-emission.ts). Gated by GHOST_LOD so ordinary line rendering
            // is unchanged when off; the discard runs before the capture writes
            // so dropped LOD pixels never reach the deferred contour either.
            #ifdef GHOST_LOD
              uniform float uLodGhostOpacity;
              float lodGhostBayer(vec2 fc) {
                int x = int(mod(fc.x, 4.0));
                int y = int(mod(fc.y, 4.0));
                int i = y * 4 + x;
                int m =
                  i == 0  ? 0  : i == 1  ? 8  : i == 2  ? 2  : i == 3  ? 10 :
                  i == 4  ? 12 : i == 5  ? 4  : i == 6  ? 14 : i == 7  ? 6  :
                  i == 8  ? 3  : i == 9  ? 11 : i == 10 ? 1  : i == 11 ? 9  :
                  i == 12 ? 15 : i == 13 ? 7  : i == 14 ? 13 : 5;
                return (float(m) + 0.5) / 16.0;
              }
            #endif

            void main() {
                #include <clipping_planes_fragment>
                #ifdef GHOST_LOD
                  if (lodGhostBayer(gl_FragCoord.xy) >= uLodGhostOpacity) discard;
                #endif
                // Per-instance highlight color (carried via the itemHighlightColor
                // instanced attribute) so that, at LOD/WIRES distance, each item keeps
                // its own color instead of all collapsing to a single uniform. See #230.
                vec3 color = mix(lodColor, vHighlightColor, vHighlight);
                #ifdef GHOST_LOD
                  float lodGhostLuma = dot(color, vec3(0.299, 0.587, 0.114));
                  color = mix(color, vec3(lodGhostLuma), 0.7) * 0.9;
                #endif
                float alpha = mix(lodOpacity, highlightOpacity, vHighlight);
                gl_FragColor = vec4(color, alpha);
                #include <colorspace_fragment>
                #ifdef CAPTURE_EMISSION
                  // A line has no surface normal; emit a camera-facing one (octahedral
                  // encode of +Z is (0,0)) so the normal buffer stays well formed.
                  gCaptureNormal = vec2(0.0);
                  // A reserved faceId, one below the capture's empty-space sentinel
                  // (0xFFFFFF), so every LOD pixel differs from the void and gets
                  // outlined. Role byte 1 keeps ambient occlusion off the line.
                  gCaptureFaceId = vec4(1.0, 1.0, 254.0 / 255.0, 1.0);
                #endif
            }
    `;
}
